  stem: "史诗类电视剧可以被视为一种文化记忆的________，其目的不仅是呈现特定时期的历史社会文本，而且也是向观众传递镌刻在历史中的社会价值和思想观念。经由历史重现，向观众传递正确的社会价值和思想观念，是史诗类电视剧创制的________。\n依次填入画横线部分最恰当的一项是：",
