  stem: "我国疆域辽阔，各地区资源禀赋各有特点，经济互补性强、依存度高。各民族始终保持________、互利共赢的经济联系，有力增强了国家整体实力，促进了中华民族共同体的形成和发展。\n填入画横线部分最恰当的一项是：",
