  stem: "利用网络存在的安全漏洞入网窃取数据信息，这种方式相当隐蔽，往往会使数据的安全响应________；而且网络中流转数据的规模十分巨大，来源异常复杂，攻击者一旦掌握网络漏洞，入侵网络后就可以在网上“________”，窃取数据。因此，必须严密防范数据在共享过程中可能遭受的各种攻击和泄露。\n依次填入画横线部分最恰当的一项是：",
