  stem: "发展新质生产力不能简单理解为________传统产业，它与发展传统产业并不矛盾。一方面，传统产业平稳发展在稳就业、稳增长等方面具有不可替代的作用；另一方面，传统产业不仅对战略性新兴产业和未来产业发展有________的支撑作用，而且可以转化为新兴产业，通过科技赋能，成为新质生产力的重要________。\n依次填入画横线部分最恰当的一项是：",
