  stem: "当前，各地纷纷布局，加快形成和发展新质生产力。然而，发展新质生产力是一项系统工程，不能盲目跟风、________，也不能脱离实际、急于求成，更不能简单复制一种模式，必须坚持从实际出发，从新质生产力的形成条件入手，考虑周全、________。\n依次填入画横线部分最恰当的一项是：",
