  stem: "巍巍华山阻住了奔腾南来的黄河，逼其90度大拐弯。原来被高原土层________着的黄河，一旦向东越过三门峡进入华北平原，顿时就变成了在平地上________的“野马”，成了到处滚动、狂奔的地上河，一会儿从东北方向流入渤海，一会儿又从东南方向夺取淮河河道注入黄海。万年千年间，黄河携带的泥沙渐渐________出了美丽富饶的华北平原。\n依次填入画横线部分最恰当的一项是：",
