  stem: "理论学习是个大课堂，基层实践也是个大课堂，党员、干部要用好这两个课堂，胸中纵有万卷，也要多到田间地头找灵感、察民情，切实解决学与做相脱节、知与行相脱离的问题。以烟火气________书卷气，有助于避免书生气、消除________的空洞感；以书卷气滋养烟火气，可以去除粗俗气，避免知识贫乏带来的无力感。\n依次填入画横线处的词语，最恰当的一项是：",
