  stem: "世界航天大国都在积极开展空间碎片清除技术研究，提出了各自的清除方案。总的来看有两大类：一类是接触式，如机械臂抓捕、安装离轨装置等；第二类是非接触式，如用激光或离子束等进行推移。两类清除方式________，都是要让碎片离开当前轨道，进入大气层烧毁。\n填入画横线部分最恰当的一项是：",
