  stem: "史书是古人写就的，有些内容可能会因有人随意取舍、记忆有误或者心存故意而________历史真实。运用基因等高科技手段的考古研究是科学，它以客观而非主观的科学事实和科学数据得出结论。科学可以检验，可以用重复操作检验此前的研究成果是否准确、正确，从而________了人为造假的可能。\n依次填入画横线部分最恰当的一项是：",
