  stem: "数字治理借助于现代信息技术手段，实现了对政府组织的流程再造与体制机制重塑，提升了公共产品和服务需求匹配的精准度，________了社会公共资源配置，增强了政府与社会以及公众之间的协同与信任，________了数字时代的人文精神，本质上就是在更加高效地创造公共价值。\n依次填入划横线部分最恰当的一项是：",
