  stem: "近日，科学家用一种________的原材料——蟹壳，制造出对环境友好的锌电池。这款电池的电解质由名为壳聚糖的生物材料制成。材料来源广泛，其中最________的来源是螃蟹和虾等甲壳类动物的外骨骼。这种新型电解质可五个月内完全分解，仅留下锌，对环境污染更小。\n依次填入画横线部分最恰当的一项是：",
