  stem: "数字经济健康发展，有利于推动构建新发展格局。当前，世界百年未有之大变局持续________，新一轮科技变革________，全球产业链趋向本土化重构。作为以数据为核心要素、以数字技术为主要手段、以互联网为重要载体的新型经济形态，数字经济正全面融入人类社会各领域。\n依次填入画横线部分最恰当的一项是：",
