  stem: "时至今日，互联网上不断刷新的信息与碎片化的记忆，让那种足以令一代人________的宏大事件越来越少了。信息变得高度密集，却又彼此孤立，而且________，快速的信息流动击穿一切时间和空间的边界，那种因为同在一个时代或同处一个地方而形成的群体意识也愈加淡薄。\n依次填入画横线部分最恰当的一项是：",
