  stem: "图画书以图为主，文字很少，看似简单，实则________，内涵很深，需要创作者有细腻的生活经验、丰厚的审美素养，并能洞悉儿童的认知特点。当前市场上图画书品质________，一个重要原因就是有些创作者脱离生活，且缺乏必要的相关素养。\n依次填入画横线部分最恰当的一项是：",
