  stem: "先秦儒学传世文献与出土文献中，存在着大量的引诗叙事。这些引诗叙事或因其义理方式不够“纯粹”，或因其文献形态不够“经典”，往往被________，甚至被忽视乃至遗忘其思想价值。然而这些引诗叙事，并不是先秦儒学诸子________的。研究先秦儒学的引诗叙事，是还原先秦儒学的原始生命、________先秦儒学的诗性智慧、彰显先秦儒学的中国哲学特质的重要路径。\n依次填入画横线部分最恰当的一项是：",
