  stem: "有研究者主张，汉语溯源应从造字义入手，揭示其特征义，结合训诂材料和文献例证，从语素相互选择和古今沟通的角度，________词语产生的构词理据和意义变化等。只有这样，才有可能真正找到字词产生的________，在纷繁复杂的词义系统里________，层层深入，探明真相。\n依次填入画横线部分最恰当的一项是：",
