  stem: "就文化优势而言，除了文本、唱腔、演艺、舞美等，杂剧还有一个别的古典文学品种________的特点，就是入世性，以及由此而来的普及性和强大影响力。几百年来，________的杂剧，潜移默化地________着民众的是非荣辱观。\n依次填入画横线部分最恰当的一项是：",
