  stem: "涉农高校应构建“宽口径、厚基础、强实践、高素质”的人才培养模式，将乡村经济社会发展和人才需求作为学科专业设置的________点，根据乡村全面振兴和基层治理需求调整学科专业结构，提高学科专业设置与乡村振兴人才需求之间的________度，全面提高人才培养质量。\n依次填入画横线部分正确的一项是（________）。",
