  stem: "北宋时，以洛阳牡丹为第一，其他地区牡丹不能与洛阳牡丹________。宋朝时河南府也成为唯一一个进贡牡丹花的地区。牡丹的大量引种，使得四川成为南宋时期牡丹的又一聚集地，尤其是天彭地区的牡丹盛况，可比肩洛阳。当然在价格上还难以________。“彭人谓花之多叶者京花，单叶者川花。近岁尤贱川花，卖不复售”。\xa0\n依次填入画横线部分最恰当的一项是：",
