  stem: "在科幻影视的发展历史中，技术是一个关键性因素。尤其是数字技术进入电影制作领域，极大________了科幻影视生产的边界，使创作者能在更广阔的科幻宇宙中遨游，建构瑰丽奇幻的艺术世界。从某种程度上讲，科幻创作________一个国家的影视技术发展水平。\n依次填入画横线部分最恰当的一项是：",
