  stem: "年度热词________大事小情，不仅反映国家大事、________时代主旋律，还有对老百姓日常生活的深切________，展现了过去一年的社会变迁和生活万象。而透过“内卷”“躺平”“鸡娃”“双减”“干饭人”等热词，我们还可________当下独特的社会景观。\n依次填入画横线部分最恰当的一项是：",
