  stem: "人类成就和文明进步的史诗，是通过历史上最有天赋和才能的个体对艺术、科学和所有其他领域所做的贡献________的。天资卓越、创造力出众的拔尖人才可以利用他们的天赋和才能来________人类社会的现状，也可以对其侵蚀破坏。而他们最终如何选择自己的道路，能否肩负起社会责任，创造更广泛的社会福祉，对于人类命运共同体的未来发展方向有________的影响。\n依次填入画横线部分最恰当的一项是：",
