  stem: "所有消费都应该建立在自己已有的经济基础之上，应该________消费、有所节制。与其被“花钱一时爽，还债三年光”的“伪精致”所累，真不如根据实际情况合理规划开支，务实购买必需品，________把日子过好。\n依次填入画横线部分最恰当的一项是：",
