  stem: "网络语言作为社会意识的一种表现形式，能够反映社会现实，生动表达民众当下心情，社会认可度高。新闻报道可以通过________网络语言中的优质部分，巧妙融入新闻报道用语，从而提升新闻报道________的能力。\n依次填入画横线处最恰当的一项是：",
