  stem: "与地震、爆炸不同，任何一场森林大火，最初都是比较________的，速度只有百米或几百米每小时，一旦发展成大火，速度会增加几十倍甚至上百倍，森林大火或特大火灾，依靠人力是很难扑灭的，它的热辐射能力非常强，防火隔离带对它________。当火线强度超过1700千瓦/米时，就超出了人类目前的灭火技术水平，只能依靠降雨、可燃物燃尽、燃至湖海等方式熄灭。因此，对于森林大火而言，________是最有效的办法。\n依次填入画横线处最恰当的一项是：",
