  stem: "访古是十分感人的经历，尤其是当我们踏上古代文献中________的地点时。亲手触摸庄重威严的利簋，秀丽铭文好像把我们拉回到三千年前牧野之战的场景，________中描绘的古代社会面貌在脑海中清晰了起来，我们感受到了历史迎面扑来的强烈震颤。这种感觉，对于考古学家来说可谓一种致命的“诱惑”。然而，身为一名严谨科学的从业者，必须对这种诱惑保持足够的警惕，维护考古记录的________，这是一名考古学者的自警，也是整个考古学学科的自尊。\n依次填入画横线处最恰当的一项是：",
