  stem: "在日常环境中，人们往往有着________的身份标签，一言一行都会影响周围人对自身的评价，所以，自然而然便保持着一种无形的________。但是，当这些社区中的“好居民”，工作中的“好职工”进入一个新的环境，其自身的身份特征________，“反正也不认识我”人们如是想着，于是一些不文明现象随之产生。\n依次填入画横线部分最恰当的一项是：",
