  stem: "“为调研而调研”等现象的出现，很大程度上就在于调研不深入、不具体。现实中，有人了解情况习惯于大而化之、________；有人调研习惯于走设计“路线”，________。这些心中不揣问题、脚下不沾泥土的错误做法，导致调研不深、不实、不细、不准，最终也会无效。\n依次填入画横线部分最恰当的一项是：",
