  stem: "传统文人画萌芽自唐，盛于宋元，讲究画外功夫。士大夫借笔墨抒胸中逸气，倡导通过绘画呈现________生命与精神境遇，与宫廷画院、民间绘画有显著差异。历来传统文人画的发展莫不在笔意图式上________，在取材上以山水花鸟、梅兰竹菊等为传统表现题材。而丰子恺的作品，打破了传统文人画发展到后期取材狭窄的限制以及风格的程式化，生命历程中一切可爱、可喜、可悲、可怒诸相皆可用水墨速写表现。\n依次填入划横线处的词语，最恰当的一项是（________）。",
