  stem: "有的文明覆灭之后，原有的民族可能还在，但文化上却被征服者彻底________。中国历史上也不乏征服与被征服，中国文明却没有因此而断裂。一个很重要的原因是中国处于半封闭的状态，东面是大海，西面是高原和荒漠，与其他地区的文明虽有接触，但相互间的交流与冲突总体来说并不________。\n依次填入画横线部分最恰当的一项是：",
