  stem: "他从不要求学生死记硬背，组织考试也________。考试通常采用开卷的方式，让学生把试卷带回去做。凡是提出自己见解的，即使是与他唱反调，只要能________，往往也能得高分。\n依次填入画横线处最恰当的一项是",
