  stem: "国际组织亦称国际团体或国际机构，是具有国际性行为特征的组织，是两个或两个以上的国家（或其他国际法主体）为实现共同的政治经济目的，依据其________的条约或其他正式法律文件建立的有一定规章制度的________机构。\n依次填入画横线处最恰当的一项是",
