  id: "2452660",
  stem: "每次去浯溪，除了看它的碑林和山水之外，最令我________的，是元结当年弹琴的浯台。那里是浯溪的最高点，每到月夜，元结总是执一把琴，坐在那里对江而弹。琴声激活了浯溪山水，浯溪山水________了他的琴声。元结与山水融合在一起，任千古忧愁万古功名顺琴声而去，随水而流，在虚无中________着沉重，在缥缈中偶尔跳出一声叹息。\n依次填入画横线处最恰当的项是：",
