  stem: "将下列选项中的词语依次填入各句横线处，最恰当的一项是：\n（1）春运是我国特别的________，1978-2020，我们经历了40多个春运，经过40多年的高速发展。我国已经从经济发展受交通瓶颈制约的国家成长为交通大国。\n（2）国务院决定，2020年4月4日举行全国性哀悼活动。在此期间，全国和驻外使领馆下半旗________，全国停止公共娱乐活动。",
