  stem: "将下列选项中的词语依次填入横线处，最恰当的一组是：\n一位学者在给中华书局百年的贺词中写道：“清末以来，中国文化传统之所以危而未倾，中华书局在以往百年中之努力与有功焉。”回望历史，此言可谓________，一个国家民族的历史文化由其典籍________，典籍存，则文化存；典籍亡，则文化亡。",
