  stem: "对人类而言，环境发挥着两方面的功能。一方面它是人类生存与发展的物质来源；另一方面它承受着各种人类活动所产生的________。这种功能决定了人类自身的活动越来越强烈地影响着环境的发展过程，因此，人类必须彻底地________利己主义，保护好环境，保持同环境和谐与协调的互利关系。\n依次填入划横线部分最恰当的一项是：",
