  stem: "旧中国“老京张”铁路的修建可谓________。由于八达岭段坡度较大，施工装备有限，投入经费不足，工人靠肩挑手凿才打通了长度仅一公里的八达岭隧道。而“新京张”铁路的修建配备最大台车、最智能盾构机、最快铺轨机，全周期智能建造、智能运维，12公里的新八达岭隧道内更建成了埋深102米的“世界最深高铁站”。施工装备与建造技术之变，正是中国________建造强国的生动缩影。\n依次填入划横线部分最恰当的一项是：",
