  stem: "关于科学革命的讨论________于十七世纪。不过，其时革命尚在________地展开，相关讨论的焦点集中在科学的本性，而未有所谓“科学革命史”的理解。到十九世纪，现代科学的基本模式逐渐定型，一些学者便回到现代科学的源头做起了编史和整理工作。\n依次填入划横线部分最恰当的一项是：",
