  stem: "贾岛“推敲”是中国古代一个名声颇显的故事，语出后蜀何光远的《鉴戒录\xb7贾忤旨》，反映了创作诗歌过程中对字句的反复________。在平时，无论阅读或写作，我们________有一字不肯放松的谨严。文学借文字表现思想情感；文字上面有含糊，就显得思想还没有________，情感还没有________。\n依次填入画横线部分最恰当的一项是：",
