  stem: "支付工具的多样化组合，提升了我国支付体系运行的质量和效率，满足了公众________支付需求。从未来支付趋势看，现金支付和非现金支付工具相互________、相互补充、共存共生的局面将长期存在。但是对我国这样一个地域广、人口多、发展很不均衡的大国来说，由于核心技术水平的限制，过度依赖非现金支付会大大增加支付体系的脆弱性。因此，必须长期________现金作为国家法定支付方式的地位，切实保障广大人民使用现金的合法权益。\n依次填入画横线处最恰当的一项是",
