  stem: "虽说海是鱼的故乡，但在海里，水族们都得奔波觅食，于缝隙间寻求生存的机会，________各种危险的攻击。但砗磲几乎没有这种尘劳，它是一种________的生命，几乎不参与任何争夺、打劫与分赃。它以富有韧劲的足丝，将身子固着在珊瑚礁上，懒得挪动半步。当海水没过全身，直觉周边没有危险临近的时候，才打开石头外壳，吐出身体柔软的部分。其软组织________的津液，具有硫酸一般的分解力，被它吸入的鱼虾，几乎无有生还的可能。\n填入划线部分最恰当的一项是：",
