  stem: "书画琴棋诗酒花，书画是文人生活________的一项。文人挂画，以营造一个清雅的环境，不仅仅是耳目之娱、社交之法，更多的是志之所向。不只是文人贵族以挂画来彰显身份地位，坊间的茶楼酒肆也多以挂名人字画来装点门面________，招揽食客。\n填入划线部分最恰当的一项是：",
