  stem: "我们应该________“动物的大脑越大越聪明”这一观念。从19世纪的颅相学到21世纪的大脑扫描科学都认为，大脑的体积决定了认知能力。但有许多事实与此不符。有人出生时只有2/3的脑组织，但成年后并无认知________。随着年龄增长，人的认知水平在提高，大脑体积却会缩小。对认知表现来说，重要的不是大脑的硬件，而是“软件”。\n依次填入画横线部分最恰当的一项是：",
