  stem: "生命在于运动，运动能塑造我们强健的身体，增强抵抗疾病的能力。当然，它对大脑也是有益的。但事实上，运动应该________，否则会使人反应迟钝。长时间大强度运动会使脑组织兴奋性降低，会使能源物质ATP（腺嘌呤核苷三磷酸）耗竭，对大脑机能造成损害。\n填入画横线部分最恰当的一项是：",
