  stem: "世界遗产指的是联合国教科文组织确认的、世界罕见的、目前无法替代的文化和自然财产。所以，成为世界文化遗产后，遗产点也不能________。事实上，申遗成功后，遗产点每年都要提交一份详细的监测报告，如地质与环境监测、气象环境监测等，接受联合国教科文组织的监督，按照高标准来________。\n依次填入划横线部分最恰当的一项是：",
