  stem: "随着社会发展和人民生活水平的不断提高，人民群众对干净的水、清新的空气、安全的食品、优美的环境等方面的要求越来越高，生态环境在群众生活幸福指数中的地位不断________，环境问题日益成为重要的民生问题。老百姓过去“盼温饱”，现在“盼环保”；过去“求________”，现在“求生态”。\n依次填入画横线部分最恰当的一项是：",
