  stem: "我们的身体里有着以各种形式存在的能量，科学家们也一直在思考用人体给可穿戴设备供电的方法，中美研究团队2013年发明了依靠运动动能发电的压电纤维，来自澳大利亚和中国的研究人员在2015年首次成功开发了能将热能转化为电能的新型面料，乍看起来，眼泪似乎是比汗水更不靠谱的燃料来源，但在2015年7月，犹他州研究人员开发出了首款集成EFC隐形眼镜，能把人的眼泪转化为电力，虽然生物动力燃料电池是目前受到追捧的新型技术，但目前发明出的设备能够产生的电力还比较有限。此外，像血液供电这类获取体内化学能量的方式，带有侵入性，也存在着许多风险。未来的生物供电究竟还有哪些可能性？或许我们可以________。\n根据以上文字，填入划横线部分最恰当的是：",
