  id: "2188046",
  stem: "社会保障关乎获得感，也等同于安全感。而放在当前的世界维度中，可以通过社会保障来________一个国家的发展诚意；发达国家的良好福利往往能对优秀青年人才产生筑巢引凤的号召效应，而一些没有迈过“中等收入陷阱”的国家，其社会保障________，尤其是对青年群体的全面覆盖________，成了他国的“前车之鉴”。\xa0\n依次填入划横线部分最恰当的一项是：",
