  stem: "经过一年多的探索，我国自然资源统一________登记试点取得积极进展。________2018年10月，12个省份、32个试点区域共划定自然资源登记单元1191个，此项登记总面积186727平方公里，并对国家公园、湿地、水流、矿产等资源进行了进一步登记试点。\n依次填入画横线部分最恰当的一项是：",
