  stem: "“不要只贪念生活的________，应该有面对暴风雨的勇气。”获得诺贝尔奖后，屠呦呦告诉记者，这句中学老师的鼓励，一直铭记于心。岩石以隆起为奋斗，所以成就山峰的巍峨；江河以奔流为奋斗，所以成就海洋的博大。人生因奋斗而精彩，所以成就生命的辉煌。正是因为有理想、有担当，敢为人先、攻坚克难，青春的风采才能刻在________的星空。\n依次填入画横线部分最恰当的一项是：",
