  stem: "如何才能做到以人为核心的新型城镇化？重要的是避免城市病。如果城市空间无序开发、人口过度集聚，重经济发展、轻环境保护，重城市建设、轻管理服务，交通拥堵问题严重，公共安全事件频发，城市污水和垃圾处理能力不足，大气、水、土壤等环境污染加剧，这样的城镇化令人望而却步，因此，我们必须通过规划，稳扎稳打，避免染上各类疾病，使城镇化既能成为发展引擎，更能提高国民的生活质量和尊严，新型城镇化才________。\n填入画横线部分最恰当的一项是：",
