  stem: "自然科学的发展遵循着其固有的逻辑：无论你提出多复杂的问题，科学家也许只用一个伟大的公式就能让你________。关于文明的研究则________，即便是最简单的问题，都需要科学家付出卓绝的努力，才能从浩如瀚海的资料中找到一个宏大的分析框架，而答案依旧不一定令人满意。\n填入画横线部分最恰当的一项是：",
