  stem: "锦官城位于成都城东南的一块开阔地，大片的厂房建立起来以后，这里终日响着________的机杼声，飘荡着蜀锦艳丽而华美的颜色。当时的政府把锦官城建在此地，是因为这里的江水漂洗出来的锦缎，质地特别________，颜色特别鲜亮；而在别的江河中漂洗，蜀锦的质地就会变得粗硬，颜色也会衰败走样。\n依次填入画横线部分最恰当的一项是：",
