  stem: "城市文明指人类创造的城市这种形式本身，以及以城市作为物质载体而创造的一切物质和精神成果。“城市文明”________着有城市出现，“文明”虽然有着更为________和抽象的含义，但是基本是指与城市和文字相联系的特定文化阶段，大多数情况下，城市与文字是同时存在的。\n依次填入画横线部分最恰当的一项是：",
