  stem: "一般人想到莎士比亚，都觉得非常遥远——他来自遥远的古代及国外，而更遥远的距离来自他的作品普遍被视为经典中的经典，自然就变得________，大众是很难亲近或理解的。其实不然，莎士比亚的戏剧之所以伟大就是因为隔了四个世纪，还能那么鲜明而深刻地映照在我们时代上，与我们________。\n依次填入画横线部分最恰当的一项是：",
