  stem: "知识产权教育是国家知识产权战略的基点，高校和大学生是国家知识产权战略的重要参与者和实践者，知识产权素质应该是大学生必备的素质。他们或许________改变社会整体知识产权意识淡薄的问题，但可以先改变自己，________，给社会树立尊重知识产权的________。\n依次填入画横线部分最恰当的一项是：",
